#!/usr/bin/env python3
"""Deterministically generate the GitHub pipeline from Pipeline IR v1.6."""
from __future__ import annotations
from pathlib import Path
import argparse,json,sys
ROOT=Path(__file__).resolve().parents[2]
CHECKOUT='de0fac2e4500dabe0009e67214ff5f5447ce83dd';SETUP_PY='a309ff8b426b58ec0e2a45f0f869d46889d02405'

def load():return json.loads((ROOT/'.adwf/pipeline-ir.json').read_text(encoding='utf-8'))
def header(name:str)->str:return f'name: {name}\n\n'
def render(ir:dict)->dict[str,str]:
    runner=ir['runner']['label'];py=ir['runtime']['python_exact'];checks=ir['required_checks']
    pr=header('ADWF PR')+f'''on:\n  pull_request:\n    types: [opened, synchronize, reopened, edited, ready_for_review]\npermissions:\n  contents: read\nenv:\n  PYTHONDONTWRITEBYTECODE: "1"\nconcurrency:\n  group: adwf-pr-${{{{ github.event.pull_request.number }}}}\n  cancel-in-progress: true\njobs:\n  fast-feedback:\n    runs-on: {runner}\n    timeout-minutes: 15\n    steps:\n      - uses: actions/checkout@{CHECKOUT}\n        with:\n          ref: ${{{{ github.event.pull_request.head.sha }}}}\n          persist-credentials: false\n          fetch-depth: 2\n      - uses: actions/setup-python@{SETUP_PY}\n        with:\n          python-version: "{py}"\n          cache: false\n      - name: Route change impact first\n        id: impact\n        run: python .adwf/scripts/impact_router.py --base "${{{{ github.event.pull_request.base.sha }}}}" --head "${{{{ github.event.pull_request.head.sha }}}}"\n      - name: Universal safety guard\n        env:\n          ADWF_BASE_SHA: ${{{{ github.event.pull_request.base.sha }}}}\n          ADWF_HEAD_SHA: ${{{{ github.event.pull_request.head.sha }}}}\n        run: |\n          python .adwf/scripts/validate_ci.py\n          python .adwf/adwf.py provider-check --input .adwf/requests/github-public-standard.json\n          python .adwf/scripts/validate_pr.py --event "$GITHUB_EVENT_PATH" --base-sha "$ADWF_BASE_SHA" --head-sha "$ADWF_HEAD_SHA"\n      - name: Framework structural/contracts gate\n        if: steps.impact.outputs.full_framework == 'true'\n        run: |\n          python .adwf/scripts/validate_framework.py\n          python .adwf/scripts/validate_pipeline_ir.py\n          python .adwf/adwf.py doctor --scope package_integrity\n          python .adwf/adwf.py doctor --scope config_health\n          python .adwf/adwf.py self-test\n      - name: Executable documentation contracts\n        if: steps.impact.outputs.docs == 'true' || steps.impact.outputs.full_framework == 'true'\n        run: python .adwf/scripts/validate_docs.py\n      - name: Provider contract suite\n        if: steps.impact.outputs.provider == 'true'\n        run: python -m unittest discover -s .adwf/tests -p 'test_provider*.py' -q\n      - name: Relevant project PR gates\n        run: python .adwf/scripts/run_project_gates.py --phase pr\n      - name: Exact-revision Playwright preview\n        if: steps.impact.outputs.preview == 'true'\n        run: python .adwf/scripts/run_preview.py --install-playwright\n'''
    control=header('ADWF Control')+f'''on:\n  workflow_run:\n    workflows: ["ADWF PR"]\n    types: [completed]\n  issue_comment:\n    types: [created]\n  pull_request_review:\n    types: [submitted]\n  workflow_dispatch:\n    inputs:\n      run_id:\n        required: false\n        type: string\n      reason:\n        required: false\n        type: string\n      request_id:\n        required: false\n        type: string\npermissions:\n  contents: read\nenv:\n  PYTHONDONTWRITEBYTECODE: "1"\nconcurrency:\n  group: adwf-control-${{{{ github.repository }}}}\n  cancel-in-progress: false\njobs:\n  trusted-controller:\n    permissions:\n      contents: write\n      actions: read\n      checks: write\n      issues: write\n      pull-requests: write\n    runs-on: {runner}\n    timeout-minutes: 15\n    steps:\n      - uses: actions/checkout@{CHECKOUT}\n        with:\n          ref: ${{{{ github.event.repository.default_branch }}}}\n          persist-credentials: false\n          fetch-depth: 2\n      - uses: actions/setup-python@{SETUP_PY}\n        with:\n          python-version: "{py}"\n          cache: false\n      - name: Trusted controller integrity\n        run: |\n          python .adwf/adwf.py provider-check --input .adwf/requests/github-public-standard.json\n          python .adwf/scripts/validate_pipeline_ir.py\n          python .adwf/adwf.py doctor --scope package_integrity\n          python .adwf/adwf.py doctor --scope config_health\n      - name: Restore public-safe durable checkpoint\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/github_runtime_sync.py --restore\n      - name: Publish trusted exact-HEAD and governance gates\n        if: github.event_name == 'workflow_run' || github.event_name == 'pull_request_review'\n        continue-on-error: true\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/publish_trusted_gate.py --event "$GITHUB_EVENT_PATH"\n      - name: Compile provider facts/evidence/AssuranceSnapshot\n        if: github.event_name == 'workflow_run'\n        continue-on-error: true\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n          ADWF_SUBJECT_SHA: ${{{{ github.event.workflow_run.head_sha }}}}\n        run: python .adwf/scripts/github_reconcile.py --apply --subject-sha "$ADWF_SUBJECT_SHA"\n      - name: Read back exact-revision preview attestation from provider logs\n        if: github.event_name == 'workflow_run'\n        continue-on-error: true\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/collect_preview_attestation.py --event "$GITHUB_EVENT_PATH"\n      - name: Complete staged GitHub bootstrap after trusted seed checks\n        if: github.event_name == 'workflow_run'\n        continue-on-error: true\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/github_bootstrap.py --apply\n      - name: Convert failed CI provider event into durable result\n        if: github.event_name == 'workflow_run'\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/runtime_event_adapter.py --event "$GITHUB_EVENT_PATH"\n      - name: Consume bounded Agent Inbox result\n        if: github.event_name == 'issue_comment'\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/consume_agent_result.py\n      - name: Execute safe Runtime Supervisor phases\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/run_active_supervisor.py\n      - name: Publish bounded Creative Agent handoff\n        if: always()\n        continue-on-error: true\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/publish_agent_request.py\n      - name: Persist public-safe checkpoint\n        if: always()\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/github_runtime_sync.py --persist\n      - name: Collect trusted CI performance evidence\n        if: always()\n        continue-on-error: true\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/github_metrics_collector.py --apply\n      - name: Refresh owner projection\n        if: always()\n        env:\n          GITHUB_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/sync_dashboard_issue.py --apply\n'''
    main=header('ADWF Main')+f'''on:\n  push:\n    branches: [main]\n  workflow_dispatch:\npermissions:\n  contents: read\nenv:\n  PYTHONDONTWRITEBYTECODE: "1"\nconcurrency:\n  group: adwf-main-${{{{ github.ref }}}}\n  cancel-in-progress: true\njobs:\n  canonical-verification:\n    runs-on: {runner}\n    timeout-minutes: 20\n    steps:\n      - uses: actions/checkout@{CHECKOUT}\n        with:\n          persist-credentials: false\n          fetch-depth: 2\n      - uses: actions/setup-python@{SETUP_PY}\n        with:\n          python-version: "{py}"\n          cache: false\n      - name: Framework contract suite\n        run: |\n          python .adwf/adwf.py provider-check --input .adwf/requests/github-public-standard.json\n          python .adwf/scripts/validate_ci.py\n          python .adwf/scripts/validate_framework.py\n          python .adwf/scripts/validate_docs.py\n          python .adwf/scripts/validate_pipeline_ir.py\n          python .adwf/adwf.py doctor --scope package_integrity\n          python .adwf/adwf.py doctor --scope config_health\n          python .adwf/adwf.py self-test\n      - name: Project main gates\n        run: python .adwf/scripts/run_project_gates.py --phase main\n'''
    release=header('ADWF Release')+f'''on:\n  workflow_dispatch:\n    inputs:\n      confirm:\n        description: "Подтверждаю выпуск уже подготовленной внутренней версии"\n        required: true\n        type: boolean\npermissions:\n  contents: read\nconcurrency:\n  group: adwf-release\n  cancel-in-progress: false\njobs:\n  release:\n    if: inputs.confirm == true && vars.ADWF_RELEASE_ENABLED == 'true'\n    permissions:\n      contents: write\n    runs-on: {runner}\n    timeout-minutes: 20\n    steps:\n      - uses: actions/checkout@{CHECKOUT}\n        with:\n          ref: ${{{{ github.event.repository.default_branch }}}}\n          persist-credentials: false\n          fetch-depth: 2\n      - uses: actions/setup-python@{SETUP_PY}\n        with:\n          python-version: "{py}"\n          cache: false\n      - name: Release internal exact version only\n        env:\n          GH_TOKEN: ${{{{ github.token }}}}\n        run: python .adwf/scripts/release.py --confirm --external --publish-github\n'''
    smoke=header('ADWF Platform Smoke')+f'''on:\n  push:\n    branches: [main]\n    paths: ['.adwf/**','START_ADWF.bat','START_ADWF.sh','.github/workflows/adwf-platform-smoke.yml']\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  smoke:\n    strategy:\n      fail-fast: false\n      matrix:\n        os: [{ir['platform_smoke']['linux']}, {ir['platform_smoke']['windows']}]\n    runs-on: ${{{{ matrix.os }}}}\n    timeout-minutes: 8\n    steps:\n      - uses: actions/checkout@{CHECKOUT}\n        with:\n          persist-credentials: false\n          fetch-depth: 1\n      - uses: actions/setup-python@{SETUP_PY}\n        with:\n          python-version: "{py}"\n          cache: false\n      - run: python .adwf/scripts/platform_smoke.py\n'''
    return {'.github/workflows/adwf-pr.yml':pr,'.github/workflows/adwf-control.yml':control,'.github/workflows/adwf-main.yml':main,'.github/workflows/adwf-release.yml':release,'.github/workflows/adwf-platform-smoke.yml':smoke}

def main()->int:
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args();rendered=render(load());errors=[]
    for rel,text in rendered.items():
        path=ROOT/rel
        if args.check:
            if not path.is_file() or path.read_text(encoding='utf-8')!=text:errors.append('PIPELINE_PROJECTION_STALE:'+rel)
        else:path.write_text(text,encoding='utf-8')
    if args.check:
        print('PIPELINE GENERATOR: '+('PASS' if not errors else 'FAIL '+','.join(errors)));return 1 if errors else 0
    print('PIPELINE PROJECTIONS generated');return 0
if __name__=='__main__':raise SystemExit(main())
